python3 -c "
import os
hits = []
for root in ['/usr/share/fonts', '/usr/local/share/fonts', os.path.expanduser('~/.fonts'), '/usr/lib']:
    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            if fn.lower().endswith(('.ttf', '.otf', '.ttc')):
                hits.append(os.path.join(dirpath, fn))
        if len(hits) > 20:
            break
    if len(hits) > 20:
        break
print('pdf font hits:', len(hits))
for h in hits[:25]:
    print(h)
"
